def transform(grid: list[list[int]]) -> list[list[int]]:
    n = len(grid)
    m = len(grid[0])
    center = n // 2

    # Find bars: for each column, determine the symmetric extent of the center row's value
    bars = []
    for c in range(m):
        val = grid[center][c]
        if val == 8:
            continue
        # Find symmetric extent
        extent = 0
        for e in range(1, center + 1):
            if grid[center - e][c] == val and grid[center + e][c] == val:
                extent = e
            else:
                break
        if extent > 0:
            bars.append((c, val, extent))

    # Sort bars by column (already in order), collect extents
    extents = sorted(b[2] for b in bars)

    # Create output grid
    result = [[8] * m for _ in range(n)]

    # Copy center row
    for c in range(m):
        result[center][c] = grid[center][c]

    # Redraw bars with new (sorted) extents
    for i, (c, val, _) in enumerate(bars):
        new_extent = extents[i]
        for e in range(-new_extent, new_extent + 1):
            r = center + e
            result[r][c] = val

    return result

def transform(grid: list[list[int]]) -> list[list[int]]:
    # Find horizontal bands (consecutive rows with same color)
    bands = []
    current_color = grid[0][0]
    current_height = 1

    for i in range(1, len(grid)):
        if grid[i][0] == current_color:
            current_height += 1
        else:
            bands.append((current_color, current_height))
            current_color = grid[i][0]
            current_height = 1
    bands.append((current_color, current_height))

    # Calculate output size
    n = len(bands)
    output_size = 2 * sum(h for _, h in bands[:-1]) + bands[-1][1]

    # Create output grid
    output = [[0] * output_size for _ in range(output_size)]

    # Fill frames from outside to inside
    offset = 0
    for i in range(n - 1):
        color, h = bands[i]
        # Fill top strip
        for row in range(offset, offset + h):
            for col in range(offset, output_size - offset):
                output[row][col] = color
        # Fill bottom strip
        for row in range(output_size - offset - h, output_size - offset):
            for col in range(offset, output_size - offset):
                output[row][col] = color
        # Fill left strip
        for row in range(offset + h, output_size - offset - h):
            for col in range(offset, offset + h):
                output[row][col] = color
        # Fill right strip
        for row in range(offset + h, output_size - offset - h):
            for col in range(output_size - offset - h, output_size - offset):
                output[row][col] = color
        offset += h

    # Fill innermost square
    color, h = bands[-1]
    for row in range(offset, offset + h):
        for col in range(offset, offset + h):
            output[row][col] = color

    return output

def transform(grid):
    rows = len(grid)
    cols = len(grid[0])

    # Step 1: Remove all 1s
    grid_no1 = [[0 if grid[r][c] == 1 else grid[r][c] for c in range(cols)] for r in range(rows)]

    # Step 2: Fill 0-cells that are between walls (colors 2-9) horizontally or vertically
    result = [row[:] for row in grid_no1]

    for r in range(rows):
        for c in range(cols):
            if grid_no1[r][c] != 0:
                continue

            # Check horizontal: wall to the left AND wall to the right in same row
            has_left = False
            has_right = False
            for c2 in range(c - 1, -1, -1):
                if grid_no1[r][c2] >= 2:
                    has_left = True
                    break
            for c2 in range(c + 1, cols):
                if grid_no1[r][c2] >= 2:
                    has_right = True
                    break

            # Check vertical: wall above AND wall below in same column
            has_above = False
            has_below = False
            for r2 in range(r - 1, -1, -1):
                if grid_no1[r2][c] >= 2:
                    has_above = True
                    break
            for r2 in range(r + 1, rows):
                if grid_no1[r2][c] >= 2:
                    has_below = True
                    break

            if (has_left and has_right) or (has_above and has_below):
                result[r][c] = 1

    return result

def transform(grid):
    rows = len(grid)
    cols = len(grid[0])

    result = [row[:] for row in grid]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0 and grid[r][c] != 1:
                continue  # non-1, non-0 cells stay as-is

            should_be_1 = False

            # Check horizontal: same-colored walls on both sides (only 0s and 1s between)
            for c_left in range(c - 1, -1, -1):
                left_val = grid[r][c_left]
                if left_val == 0 or left_val == 1:
                    continue
                # Found a wall to the left
                for c_right in range(c + 1, cols):
                    right_val = grid[r][c_right]
                    if right_val == 0 or right_val == 1:
                        continue
                    # Found a wall to the right
                    if left_val == right_val:
                        should_be_1 = True
                    break
                break

            # Check vertical: same-colored walls above and below (only 0s and 1s between)
            if not should_be_1:
                for r_up in range(r - 1, -1, -1):
                    up_val = grid[r_up][c]
                    if up_val == 0 or up_val == 1:
                        continue
                    # Found a wall above
                    for r_down in range(r + 1, rows):
                        down_val = grid[r_down][c]
                        if down_val == 0 or down_val == 1:
                            continue
                        # Found a wall below
                        if up_val == down_val:
                            should_be_1 = True
                        break
                    break

            result[r][c] = 1 if should_be_1 else 0

    return result

def transform(grid):
    import numpy as np
    from collections import Counter

    grid = [list(row) for row in grid]
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    if rows == 0 or cols == 0:
        return grid

    # Identify background (most common color) and shape color
    all_colors = [grid[r][c] for r in range(rows) for c in range(cols)]
    color_counts = Counter(all_colors)
    background = color_counts.most_common(1)[0][0]

    shape_color = None
    for color, count in color_counts.most_common():
        if color != background and color != 4:
            shape_color = color
            break

    # Find 4-pattern columns
    four_cols = set()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 4:
                four_cols.add(c)

    if not four_cols:
        return grid

    four_min_col = min(four_cols)
    four_max_col = max(four_cols)

    # Rows where 4-pattern appears in output
    four_rows = [2, 4, 8, 10, 14, 16, 20, 22, 26, 28]
    # Gap rows where 3s appear instead
    gap_rows = [0, 6, 12, 18, 24]

    # Build output
    output = [row[:] for row in grid]

    # Place 4s at 4-row positions
    for r in four_rows:
        if r < rows:
            for c in range(four_min_col, four_max_col + 1):
                if c < cols:
                    output[r][c] = 4

    # Place 3s at gap rows
    for r in gap_rows:
        if r >= rows:
            continue
        # Find shape cells in this row
        shape_cells = set()
        for c in range(cols):
            if grid[r][c] == shape_color:
                shape_cells.add(c)

        # Dilate by 1
        dilated = set()
        for c in shape_cells:
            for dc in [-1, 0, 1]:
                nc = c + dc
                if 0 <= nc < cols:
                    dilated.add(nc)

        # Add 4-pattern columns
        for c in range(four_min_col, four_max_col + 1):
            if c < cols:
                dilated.add(c)

        # Place 3s
        for c in dilated:
            output[r][c] = 3

    return output

