from collections import Counter

def transform(grid):
    grid = [list(row) for row in grid]
    H = len(grid)
    W = len(grid[0])
    result = [row[:] for row in grid]

    if H < 3 or W < 3:
        return result

    # Determine border color (most common on edges)
    edge_cells = []
    for c in range(W):
        edge_cells.append(grid[0][c])
        edge_cells.append(grid[H-1][c])
    for r in range(H):
        edge_cells.append(grid[r][0])
        edge_cells.append(grid[r][W-1])
    bc = Counter(edge_cells).most_common(1)[0][0]

    # Find border columns (columns where all cells are border color)
    border_cols = set()
    for c in range(W):
        if all(grid[r][c] == bc for r in range(H)):
            border_cols.add(c)

    # Sort border columns to find segments
    bc_sorted = sorted(border_cols)
    segments = []
    for i in range(len(bc_sorted) - 1):
        c1, c2 = bc_sorted[i], bc_sorted[i+1]
        if c2 - c1 > 2:  # at least 1 inner column
            segments.append((c1 + 1, c2 - 1))

    if not segments:
        return result

    for (c1, c2) in segments:
        sub_w = c2 - c1 + 1
        if sub_w < 3:
            continue

        # Determine sub-border color from top/bottom of this segment
        top_vals = [grid[1][c] for c in range(c1, c2 + 1) if 1 < H - 1]
        bot_vals = [grid[H-2][c] for c in range(c1, c2 + 1) if H > 3]
        all_border_vals = top_vals + bot_vals
        if not all_border_vals:
            continue
        sbc = Counter(all_border_vals).most_common(1)[0][0]

        # Find sub-border rows (rows where all cells in segment are sub-border color)
        sub_border_rows = set()
        for r in range(H):
            if all(grid[r][c] == sbc for c in range(c1, c2 + 1)):
                sub_border_rows.add(r)

        # Find row segments between sub-border rows
        sbr_sorted = sorted(sub_border_rows)
        row_segments = []
        for i in range(len(sbr_sorted) - 1):
            r1, r2 = sbr_sorted[i], sbr_sorted[i+1]
            if r2 - r1 > 2:
                row_segments.append((r1 + 1, r2 - 1))

        if not row_segments:
            continue

        for (r1, r2) in row_segments:
            inner_h = r2 - r1 + 1
            if inner_h < 1:
                continue

            # Determine sub-sub-border color (from edges of this inner block)
            edge2 = []
            for c in range(c1, c2 + 1):
                edge2.append(grid[r1][c])
                edge2.append(grid[r2][c])
            for r in range(r1, r2 + 1):
                edge2.append(grid[r][c1])
                edge2.append(grid[r][c2])
            ssbc = Counter(edge2).most_common(1)[0][0]

            # Find content cells (not sub-sub-border color)
            content_cells = []
            for r in range(r1, r2 + 1):
                for c in range(c1, c2 + 1):
                    if grid[r][c] != ssbc:
                        content_cells.append((r, c))

            if not content_cells:
                continue

            # Determine dominant period
            best_L = 1
            best_score = len(content_cells)

            for L in range(1, inner_h + 1):
                groups = {}
                for (r, c) in content_cells:
                    key = (r - r1) % L
                    if key not in groups:
                        groups[key] = []
                    groups[key].append(grid[r][c])

                # Determine pattern value for each key
                pattern = {}
                for key, vals in groups.items():
                    pattern[key] = Counter(vals).most_common(1)[0][0]

                # Count mismatches
                mismatches = sum(1 for (r, c) in content_cells 
                               if grid[r][c] != pattern[(r - r1) % L])

                if mismatches < best_score:
                    best_score = mismatches
                    best_L = L

            # Apply pattern
            if best_score < len(content_cells):
                groups = {}
                for (r, c) in content_cells:
                    key = (r - r1) % best_L
                    if key not in groups:
                        groups[key] = []
                    groups[key].append(grid[r][c])

                pattern = {}
                for key, vals in groups.items():
                    pattern[key] = Counter(vals).most_common(1)[0][0]

                for (r, c) in content_cells:
                    result[r][c] = pattern[(r - r1) % best_L]

    return result

