def transform(grid):
    H = len(grid)
    W = len(grid[0])
    result = [row[:] for row in grid]

    # Find border color (most common on edges)
    edge_cells = []
    for c in range(W):
        edge_cells.append(grid[0][c])
        edge_cells.append(grid[H-1][c])
    for r in range(H):
        edge_cells.append(grid[r][0])
        edge_cells.append(grid[r][W-1])
    bc = Counter(edge_cells).most_common(1)[0][0]

    # Find rows entirely border color
    border_rows = set()
    for r in range(H):
        if all(grid[r][c] == bc for c in range(W)):
            border_rows.add(r)

    # Find cols entirely border color
    border_cols = set()
    for c in range(W):
        if all(grid[r][c] == bc for r in range(H)):
            border_cols.add(c)

    # Get sorted lists
    br_sorted = sorted(border_rows)
    bc_sorted = sorted(border_cols)

    # Find blocks (rectangular regions between border rows and cols)
    row_ranges = []
    for i in range(len(br_sorted) - 1):
        r1, r2 = br_sorted[i] + 1, br_sorted[i+1] - 1
        if r1 <= r2:
            row_ranges.append((r1, r2))

    col_ranges = []
    for i in range(len(bc_sorted) - 1):
        c1, c2 = bc_sorted[i] + 1, bc_sorted[i+1] - 1
        if c1 <= c2:
            col_ranges.append((c1, c2))

    if not row_ranges or not col_ranges:
        return result

    for (r1, r2) in row_ranges:
        for (c1, c2) in col_ranges:
            block_h = r2 - r1 + 1
            block_w = c2 - c1 + 1
            if block_h < 3 or block_w < 3:
                continue

            # Find sub-border color from edges of this block
            edge_cells2 = []
            for c in range(c1, c2 + 1):
                edge_cells2.append(grid[r1][c])
                edge_cells2.append(grid[r2][c])
            for r in range(r1, r2 + 1):
                edge_cells2.append(grid[r][c1])
                edge_cells2.append(grid[r][c2])
            sbc = Counter(edge_cells2).most_common(1)[0][0]

            # Content region (inside sub-border)
            cr1, cr2 = r1 + 1, r2 - 1
            cc1, cc2 = c1 + 1, c2 - 1
            content_h = cr2 - cr1 + 1
            content_w = cc2 - cc1 + 1

            if content_h < 1 or content_w < 1:
                continue

            # Extract content
            content = [[grid[r][c] for c in range(cc1, cc2 + 1)] for r in range(cr1, cr2 + 1)]

            # Determine direction
            use_horizontal = content_w >= content_h

            if use_horizontal:
                # Find best period per row
                for r in range(content_h):
                    row = content[r]
                    n = len(row)
                    best_L = 1
                    best_score = n
                    for L in range(1, n + 1):
                        groups = {}
                        for i in range(n):
                            key = i % L
                            if key not in groups:
                                groups[key] = []
                            groups[key].append(row[i])
                        mismatches = 0
                        for key, vals in groups.items():
                            mc = Counter(vals).most_common(1)[0][0]
                            mismatches += sum(1 for v in vals if v != mc)
                        if mismatches < best_score:
                            best_score = mismatches
                            best_L = L
                    # Apply
                    if best_score < n:
                        groups = {}
                        for i in range(n):
                            key = i % best_L
                            if key not in groups:
                                groups[key] = []
                            groups[key].append(row[i])
                        for key, vals in groups.items():
                            mc = Counter(vals).most_common(1)[0][0]
                            for i in range(n):
                                if i % best_L == key:
                                    content[r][i] = mc
            else:
                # Find best period per column
                for c in range(content_w):
                    col = [content[r][c] for r in range(content_h)]
                    n = len(col)
                    best_L = 1
                    best_score = n
                    for L in range(1, n + 1):
                        groups = {}
                        for i in range(n):
                            key = i % L
                            if key not in groups:
                                groups[key] = []
                            groups[key].append(col[i])
                        mismatches = 0
                        for key, vals in groups.items():
                            mc = Counter(vals).most_common(1)[0][0]
                            mismatches += sum(1 for v in vals if v != mc)
                        if mismatches < best_score:
                            best_score = mismatches
                            best_L = L
                    # Apply
                    if best_score < n:
                        groups = {}
                        for i in range(n):
                            key = i % best_L
                            if key not in groups:
                                groups[key] = []
                            groups[key].append(col[i])
                        for key, vals in groups.items():
                            mc = Counter(vals).most_common(1)[0][0]
                            for i in range(n):
                                if i % best_L == key:
                                    content[i][c] = mc

            # Write back
            for r in range(content_h):
                for c in range(content_w):
                    result[cr1 + r][cc1 + c] = content[r][c]

    return result

from collections import deque
import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    arr = np.array(grid)
    h, w = arr.shape

    # Step 1: Find background (most common border color)
    border = []
    for i in range(h):
        border.append(int(arr[i, 0]))
        border.append(int(arr[i, w-1]))
    for j in range(w):
        border.append(int(arr[0, j]))
        border.append(int(arr[h-1, j]))
    bg = int(np.bincount(border).argmax())

    # Step 2: Find all 4-connected components of same non-bg color
    visited = np.zeros((h, w), dtype=bool)
    components = {}  # color -> list of cells

    for i in range(h):
        for j in range(w):
            if arr[i, j] != bg and not visited[i, j]:
                color = int(arr[i, j])
                queue = deque([(i, j)])
                visited[i, j] = True
                cells = []
                while queue:
                    ci, cj = queue.popleft()
                    cells.append((ci, cj))
                    for di, dj in [(-1,0),(1,0),(0,-1),(0,1)]:
                        ni, nj = ci+di, cj+dj
                        if 0 <= ni < h and 0 <= nj < w and not visited[ni, nj] and arr[ni, nj] == color:
                            visited[ni, nj] = True
                            queue.append((ni, nj))
                if color in components:
                    components[color].extend(cells)
                else:
                    components[color] = cells

    # Step 3: Identify fill (largest) and source (second largest) colors
    sorted_colors = sorted(components.keys(), key=lambda c: len(components[c]), reverse=True)
    if len(sorted_colors) < 2:
        return grid
    fill_color = sorted_colors[0]
    source_color = sorted_colors[1]

    fill_cells = set(components[fill_color])
    source_cells = set(components[source_color])

    # Step 4: Extract pattern from source objects (non-bg, non-fill, non-source cells)
    pattern = []
    for i in range(h):
        for j in range(w):
            v = int(arr[i, j])
            if v != bg and v != fill_color and v != source_color:
                if not pattern or pattern[-1] != v:
                    pattern.append(v)

    if not pattern:
        return grid

    # Step 5: Build target region = source cells + source object cells
    source_obj_cells = []
    for i in range(h):
        for j in range(w):
            v = int(arr[i, j])
            if v != bg and v != fill_color and v != source_color:
                source_obj_cells.append((i, j))

    target_cells = list(source_cells) + source_obj_cells
    target_set = set(target_cells)

    # Step 6: Assign pattern values using anti-diagonal (row+col) ordering
    # First occurrence of each unique sum gets the next pattern value
    sums = sorted(set(r + c for r, c in target_cells))
    sum_to_val = {}
    for idx, s in enumerate(sums):
        sum_to_val[s] = pattern[idx % len(pattern)]

    # Step 7: Build output
    result = arr.copy()
    # Replace source objects with source color
    for (i, j) in source_obj_cells:
        result[i, j] = source_color
    # Fill target region with pattern
    for (i, j) in target_cells:
        result[i, j] = sum_to_val[i + j]

    return result.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    h, w = len(grid), len(grid[0])
    flat = [grid[i][j] for i in range(h) for j in range(w)]
    bg = max(set(flat), key=flat.count)

    out_h = h // 2
    out_w = w // 2
    result = []
    for i in range(out_h):
        row = []
        for j in range(out_w):
            block = [grid[2*i][2*j], grid[2*i][2*j+1],
                     grid[2*i+1][2*j], grid[2*i+1][2*j+1]]
            non_bg = [c for c in block if c != bg]
            if non_bg:
                row.append(max(set(non_bg), key=non_bg.count))
            else:
                row.append(bg)
        result.append(row)

    # Trim background-only borders
    while len(result) > 0 and all(c == bg for c in result[0]):
        result = result[1:]
    while len(result) > 0 and all(c == bg for c in result[-1]):
        result = result[:-1]
    if result:
        while len(result[0]) > 0 and all(row[0] == bg for row in result):
            result = [row[1:] for row in result]
        while len(result[0]) > 0 and all(row[-1] == bg for row in result):
            result = [row[:-1] for row in result]

    return result

def transform(grid):
    grid = [list(row) for row in grid]
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    # Find 5s bounding box → output dimensions
    fives = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 5]
    if not fives:
        return [row[:] for row in grid]

    min_r = min(r for r, c in fives)
    max_r = max(r for r, c in fives)
    min_c = min(c for r, c in fives)
    max_c = max(c for r, c in fives)
    out_h = max_r - min_r + 1
    out_w = max_c - min_c + 1

    # Find connected components of non-zero, non-5 cells
    visited = set()
    components = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0 and grid[r][c] != 5 and (r, c) not in visited:
                comp = []
                queue = [(r, c)]
                visited.add((r, c))
                while queue:
                    cr, cc = queue.pop(0)
                    comp.append((cr, cc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if (nr, nc) not in visited and grid[nr][nc] != 0 and grid[nr][nc] != 5:
                                visited.add((nr, nc))
                                queue.append((nr, nc))
                components.append(comp)

    if not components:
        return [[0] * out_w for _ in range(out_h)]

    # Find dominant component (most cells)
    dominant = max(components, key=len)
    dominant_sorted = sorted(dominant)
    colors_in_order = [grid[r][c] for r, c in dominant_sorted]

    # Get unique colors in order of first appearance
    unique_colors = list(dict.fromkeys(colors_in_order))

    result = [[0] * out_w for _ in range(out_h)]

    # Traverse the frame in order: top row L->R, right col T->B (excl top), 
    # bottom row R->L (excl right), left col B->T (excl top and bottom)
    frame_positions = []
    for c in range(out_w):
        frame_positions.append((0, c))
    for r in range(1, out_h):
        frame_positions.append((r, out_w - 1))
    if out_h > 1:
        for c in range(out_w - 2, -1, -1):
            frame_positions.append((out_h - 1, c))
    if out_w > 1:
        for r in range(out_h - 2, 0, -1):
            frame_positions.append((r, 0))

    # Assign colors to frame positions
    for i, (fr, fc) in enumerate(frame_positions):
        if len(unique_colors) == 1:
            result[fr][fc] = unique_colors[0]
        else:
            color_idx = int(i * len(colors_in_order) / len(frame_positions))
            result[fr][fc] = colors_in_order[color_idx]

    return result

