    left_col.sort(key=lambda o: o['min_r'])
    right_col.sort(key=lambda o: o['min_r'])

    ordered = left_col + right_col

    # Place objects in output
    cur_row = 1
    for i, obj in enumerate(ordered):
        pair_idx = i // 2
        col_offset = (i % 2) * 2
        length = len(obj['pixels'])
