                            nr, nc = cr + dr, cc + dc
                            if 0 <= nr < rows and 0 <= nc < left_w:
                                if not visited[nr][nc] and left[nr][nc] == color:
                                    visited[nr][nc] = True
                                    queue.append((nr, nc))

                min_r = min(p[0] for p in pixels)
                max_r = max(p[0] for p in pixels)
                min_c = min(p[1] for p in pixels)
                max_c = max(p[1] for p in pixels)
                height = max_r - min_r + 1
                width = max_c - min_c + 1

                # Determine if vertical: check for internal (fully surrounded) cells
                pixel_set = set(pixels)
                is_vertical = False
                for (pr, pc) in pixels:
                    if all((pr+dr, pc+dc) in pixel_set 
                          for dr in [-1,0,1] for dc in [-1,0,1] if not (dr==0 and dc==0)):
                        is_vertical = True
                        break

                line_len = height if is_vertical else width

                objects.append({
                    'color': color,
                    'is_vertical': is_vertical,
                    'line_len': line_len,
                    'min_r': min_r,
                    'min_c': min_c
                })

