    # Within each group, sort left first then right
    ordered = []
    for group in groups:
        group.sort(key=lambda o: (o['min_c'] >= mid, o['min_r']))
        ordered.extend(group)

    # Place objects in output
    cur_r = 1
    cur_c = max(0, 5 - inst_col)

