def transform(grid):
    if not grid or not grid[0]:
        return grid

    rows = len(grid)
    cols = len(grid[0])

    nz = [(r, c, grid[r][c]) for r in range(rows) for c in range(cols) if grid[r][c] != 0]

    if not nz:
        return [row[:] for row in grid]

    row_counts = {}
    col_counts = {}
    for r, c, v in nz:
        row_counts[r] = row_counts.get(r, 0) + 1
        col_counts[c] = col_counts.get(c, 0) + 1

    multi_rows = sum(1 for v in row_counts.values() if v >= 2)
    multi_cols = sum(1 for v in col_counts.values() if v >= 2)

    result = [row[:] for row in grid]

    if multi_rows >= multi_cols:
        # Horizontal fill
        for r in sorted(row_counts.keys()):
            if row_counts[r] < 2:
                continue
            cells = sorted([(c, v) for (rr, c, v) in nz if rr == r])
            positions = [c for c, v in cells]
            values = [v for c, v in cells]
            gaps = [positions[i+1] - positions[i] for i in range(len(positions)-1)]
            period = min(gaps)

            # Determine phase: most common pos%period, tie-break by closest to rightmost
            phase_counts = {}
            for p in positions:
                ph = p % period
                phase_counts[ph] = phase_counts.get(ph, 0) + 1
            max_count = max(phase_counts.values())
            candidates = [ph for ph, cnt in phase_counts.items() if cnt == max_count]
            if len(candidates) == 1:
                phase = candidates[0]
            else:
                # Pick phase closest to rightmost position
                rightmost = positions[-1]
                phase = max(candidates, key=lambda ph: rightmost - (rightmost % period - ph) % period)

            # Fill value
            in_phase = [(pos, val) for pos, val in zip(positions, values) if pos % period == phase]
            out_phase = [(pos, val) for pos, val in zip(positions, values) if pos % period != phase]
            if out_phase:
                fill_val = out_phase[-1][1]  # rightmost outlier
            else:
                fill_val = in_phase[0][1]    # leftmost in-phase

            # Fill from first to last anchor
            first, last = positions[0], positions[-1]
            for c in range(first, last + 1):
                if c % period == phase:
                    result[r][c] = fill_val
    else:
        # Vertical fill
        for c in sorted(col_counts.keys()):
            if col_counts[c] < 2:
                continue
            cells = sorted([(r, v) for (r, cc, v) in nz if cc == c])
            positions = [r for r, v in cells]
            values = [v for r, v in cells]
            gaps = [positions[i+1] - positions[i] for i in range(len(positions)-1)]
            period = min(gaps)

            # Determine phase
            phase_counts = {}
            for p in positions:
                ph = p % period
                phase_counts[ph] = phase_counts.get(ph, 0) + 1
            max_count = max(phase_counts.values())
            candidates = [ph for ph, cnt in phase_counts.items() if cnt == max_count]
            if len(candidates) == 1:
                phase = candidates[0]
            else:
                bottom = positions[-1]
                phase = max(candidates, key=lambda ph: bottom - (bottom % period - ph) % period)

            # Fill value
            in_phase = [(pos, val) for pos, val in zip(positions, values) if pos % period == phase]
            out_phase = [(pos, val) for pos, val in zip(positions, values) if pos % period != phase]
            if out_phase:
                fill_val = out_phase[-1][1]  # bottom-most outlier
            else:
                fill_val = in_phase[0][1]    # top-most in-phase

            # Fill from first to last anchor
            first, last = positions[0], positions[-1]
            for r in range(first, last + 1):
                if r % period == phase:
                    result[r][c] = fill_val

    return result

def transform(grid):
    if not grid or not grid[0]:
        return grid

    rows = len(grid)
    cols = len(grid[0])

    # Find connected components (4-connected)
    visited = [[False]*cols for _ in range(rows)]
    components = []

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] != 0 and not visited[i][j]:
                color = grid[i][j]
                # BFS
                queue = [(i, j)]
                visited[i][j] = True
                cells = []
                while queue:
                    r, c = queue.pop(0)
                    cells.append((r, c))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = r+dr, c+dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if not visited[nr][nc] and grid[nr][nc] == color:
                                visited[nr][nc] = True
                                queue.append((nr, nc))
                components.append((color, cells))

    # Determine tip and direction for each component
    grid_r = rows - 1
    grid_c = cols - 1

    for color, cells in components:
        rs = [r for r, c in cells]
        cs = [c for c_r, c in cells]

        if len(cells) == 1:
            tip = cells[0]
        else:
            max_r, min_r = max(rs), min(rs)
            max_c, min_c = max(cs), min(cs)
            span_r = max_r - min_r
            span_c = max_c - min_c

            if span_r > 0 and span_c == 0:
                # Vertical line
                avg_c = sum(cs) / len(cs)
                if min_c < grid_c / 2:
                    tip = (min_r, cells[0][1])  # top end
                else:
                    tip = (max_r, cells[0][1])  # bottom end
            elif span_c > 0 and span_r == 0:
                # Horizontal line
                avg_r = sum(rs) / len(rs)
                if min_r < grid_r / 2:
                    tip = (cells[0][0], max_c)  # right end
                else:
                    tip = (cells[0][0], min_c)  # left end
            elif span_r > 0 and span_c > 0:
                # L-shape or rectangle
                # Count neighbors for each cell to find degree-1 cells (points)
                cell_set = set(cells)
                points = []
                for (r, c) in cells:
                    neighbors = sum(1 for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]
                                   if (r+dr, c+dc) in cell_set)
                    if neighbors == 1:
                        points.append((r, c))

                if len(points) == 1:
                    tip = points[0]
                elif len(points) >= 2:
                    # Rectangle - use bottom-right corner
                    tip = (max_r, max_c)
                else:
                    tip = (max_r, max_c)
            else:
                tip = cells[0]

        # Determine direction
        avg_r = sum(rs) / len(rs)
        avg_c = sum(cs) / len(cs)

        dr = 1 if avg_r < grid_r / 2 else -1
        dc = 1 if avg_c > grid_c / 2 else -1

        # Draw beam
        r, c = tip[0], tip[1]
        while 0 <= r < rows and 0 <= c < cols:
            if grid[r][c] == 0:
                grid[r][c] = color
            r += dr
            c += dc

    return grid

def transform(grid):
    rows = len(grid)
    cols = len(grid[0])
    result = [row[:] for row in grid]

    visited = [[False]*cols for _ in range(rows)]

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] != 0 and not visited[i][j]:
                color = grid[i][j]
                # BFS to find connected component
                queue = [(i, j)]
                visited[i][j] = True
                cells = []
                while queue:
                    r, c = queue.pop(0)
                    cells.append((r, c))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = r+dr, c+dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if not visited[nr][nc] and grid[nr][nc] == color:
                                visited[nr][nc] = True
                                queue.append((nr, nc))

                if len(cells) == 1:
                    tip = cells[0]
                else:
                    rs = [r for r, c in cells]
                    cs = [c for r, c in cells]
                    max_r, min_r = max(rs), min(rs)
                    max_c, min_c = max(cs), min(cs)
                    span_r = max_r - min_r
                    span_c = max_c - min_c

                    if span_r > 0 and span_c == 0:
                        # Vertical line: tip is top
                        tip = (min_r, cells[0][1])
                    elif span_c > 0 and span_r == 0:
                        # Horizontal line: tip is rightmost
                        tip = (cells[0][0], max_c)
                    else:
                        # L-shape or block: find corner (degree-2 in 4-connected)
                        cell_set = set(cells)
                        corners = []
                        for (r, c) in cells:
                            deg = sum(1 for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]
                                     if (r+dr, c+dc) in cell_set)
                            if deg == 2:
                                corners.append((r, c))
                        if len(corners) == 1:
                            tip = corners[0]
                        else:
                            # 2x2+ block: use top-right
                            tip = (min_r, max_c)

                # Determine beam direction
                tr, tc = tip
                dr = 1 if tr < rows / 2.0 else -1
                dc = 1 if tc >= cols / 2.0 else -1

                # Draw beam
                r, c = tr + dr, tc + dc
                while 0 <= r < rows and 0 <= c < cols:
                    if result[r][c] != 0:
                        break
                    result[r][c] = color
                    r += dr
                    c += dc

    return result

import numpy as np
from collections import deque

def transform(grid):
    h = len(grid)
    w = len(grid[0])

    # Find the bar
    bar_color = None
    bar_top = None
    bar_bot = None
    for color in range(1, 10):
        full_rows = []
        for r in range(h):
            count = sum(1 for c in range(w) if grid[r][c] == color)
            if count > 0.8 * w:
                full_rows.append(r)
        if full_rows:
            # Find longest consecutive run
            best_run = []
            run = [full_rows[0]]
            for i in range(1, len(full_rows)):
                if full_rows[i] == full_rows[i-1] + 1:
                    run.append(full_rows[i])
                else:
                    if len(run) > len(best_run):
                        best_run = run
                    run = [full_rows[i]]
            if len(run) > len(best_run):
                best_run = run
            if len(best_run) >= 3:
                bar_color = color
                bar_top = best_run[0]
                bar_bot = best_run[-1]
                break

    if bar_color is None:
        return [row[:] for row in grid]

    # Create mask for non-bar, non-zero cells
    mask = np.zeros((h, w), dtype=bool)
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 and grid[r][c] != bar_color:
                mask[r, c] = True

    # Find connected components (4-connected)
    visited = np.zeros((h, w), dtype=bool)
    shapes = []
    for r in range(h):
        for c in range(w):
            if mask[r, c] and not visited[r, c]:
                # BFS
                queue = deque([(r, c)])
                visited[r, c] = True
                cells = []
                while queue:
                    cr, cc = queue.popleft()
                    cells.append((cr, cc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < h and 0 <= nc < w and mask[nr, nc] and not visited[nr, nc]:
                            visited[nr, nc] = True
                            queue.append((nr, nc))
                # Extract shape
                min_r = min(x[0] for x in cells)
                max_r = max(x[0] for x in cells)
                min_c = min(x[1] for x in cells)
                max_c = max(x[1] for x in cells)
                sh_h = max_r - min_r + 1
                sh_w = max_c - min_c + 1
                sh = [[0]*sh_w for _ in range(sh_h)]
                for (cr, cc) in cells:
                    sh[cr - min_r][cc - min_c] = grid[cr][cc]
                center_row = (min_r + max_r) / 2.0
                shapes.append({'data': sh, 'h': sh_h, 'w': sh_w, 'center_row': center_row})

    if not shapes:
        return [row[:] for row in grid]

    # Determine column positions
    above_shapes = [s for s in shapes if s['center_row'] < bar_top]
    below_shapes = [s for s in shapes if s['center_row'] > bar_bot]
    num_above = len(above_shapes)
    num_below = len(below_shapes)

    if num_above > 0 and num_below > 0:
        # Two merged shapes: above at left, below at right
        total_w = sum(s['w'] for s in above_shapes) + sum(s['w'] for s in below_shapes)
        start_col = max(0, (w - total_w) // 2)
        above_col = start_col
        below_col = start_col + sum(s['w'] for s in above_shapes)
    else:
        # One merged shape: centered
        all_shapes = above_shapes + below_shapes
        total_w = sum(s['w'] for s in all_shapes)
        start_col = max(0, (w - total_w) // 2)
        above_col = start_col
        below_col = start_col

    def build_merged(comp_shapes, col):
        if not comp_shapes:
            return
        total_h = sum(s['h'] for s in comp_shapes)
        merged = [[0]*w for _ in range(total_h)]
        offset = 0
        for s in comp_shapes:
            for r in range(s['h']):
                for c in range(s['w']):
                    if s['data'][r][c] != 0:
                        merged[offset + r][col + c] = s['data'][r][c]
            offset += s['h']
        return merged

    # Build above merged shape
    above_merged = None
    if above_shapes:
        above_shapes_sorted = sorted(above_shapes, key=lambda s: s['center_row'], reverse=True)
        above_merged = build_merged(above_shapes_sorted, above_col)

    # Build below merged shape
    below_merged = None
    if below_shapes:
        below_shapes_sorted = sorted(below_shapes, key=lambda s: s['center_row'])
        below_merged = build_merged(below_shapes_sorted, below_col)

    # Create output
    result = [[0]*w for _ in range(h)]

    # Place bar
    for r in range(bar_top, bar_bot + 1):
        for c in range(w):
            result[r][c] = grid[r][c]

    # Place above merged shape (bottom row at bar_top - 1)
    if above_merged:
        am_h = len(above_merged)
        start_row = bar_top - am_h
        for r in range(am_h):
            if 0 <= start_row + r < h:
                for c in range(w):
                    if above_merged[r][c] != 0:
                        result[start_row + r][c] = above_merged[r][c]

    # Place below merged shape (top row at bar_bot + 1)
    if below_merged:
        bm_h = len(below_merged)
        start_row = bar_bot + 1
        for r in range(bm_h):
            if 0 <= start_row + r < h:
                for c in range(w):
                    if below_merged[r][c] != 0:
                        result[start_row + r][c] = below_merged[r][c]

    return result

import numpy as np
import math
from collections import defaultdict

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    W = len(grid[0])

    # Find all non-zero cells
    cells = {}
    for r in range(H):
        for c in range(W):
            if grid[r][c] != 0:
                cells[(r,c)] = grid[r][c]

    # Classify: anchors (isolated) vs fixed (adjacent to same color)
    anchors = {}
    fixed = {}
    for (r,c), v in cells.items():
        adj_same = False
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] == v:
                adj_same = True
                break
        if adj_same:
            fixed[(r,c)] = v
        else:
            anchors[(r,c)] = v

    # Group anchors by color
    color_anchors = defaultdict(list)
    for (r,c), v in anchors.items():
        color_anchors[v].append((r,c))

    # Sort colors: outermost first (by min r+c of anchors)
    color_order = sorted(color_anchors.keys(), key=lambda v: (
        min(r+c for r,c in color_anchors[v]),
        min(r for r,c in color_anchors[v]),
        min(c for r,c in color_anchors[v])
    ))

    # Build result
    result = [[0]*W for _ in range(H)]

    # Draw each color's shape (outer to inner, inner overwrites)
    for color in color_order:
        pts = color_anchors[color]
        draw_shape(result, color, pts, color_order, color_anchors, fixed, H, W)

    # Place fixed cells (only where not already covered by inner shapes)
    for (r,c), v in fixed.items():
        if result[r][c] == 0:
            result[r][c] = v

    return result

def draw_shape(result, color, pts, color_order, color_anchors, fixed, H, W):
    idx = color_order.index(color)

    if len(pts) == 1:
        # Single anchor: bounding box of all inner content + this point
        inner_pts = list(pts)
        for c2 in color_order[idx+1:]:
            inner_pts.extend(color_anchors[c2])
        if fixed:
            inner_pts.extend(fixed.keys())

        min_r = min(p[0] for p in inner_pts)
        max_r = max(p[0] for p in inner_pts)
        min_c = min(p[1] for p in inner_pts)
        max_c = max(p[1] for p in inner_pts)

        # Draw rectangle border
        for c in range(min_c, max_c+1):
            result[min_r][c] = color
            result[max_r][c] = color
        for r in range(min_r, max_r+1):
            result[r][min_c] = color
            result[r][max_c] = color

    elif len(pts) == 2:
        # Line between two points
        draw_line_thick(result, pts[0], pts[1], color, H, W)
    else:
        # Multiple points: polygon border
        polygon = order_polygon(pts)
        for i in range(len(polygon)):
            p1 = polygon[i]
            p2 = polygon[(i+1) % len(polygon)]
            draw_line_thick(result, p1, p2, color, H, W)

def draw_line_thick(result, p1, p2, color, H, W):
    r1, c1 = p1
    r2, c2 = p2
    dr = r2 - r1
    dc = c2 - c1
    steps = max(abs(dr), abs(dc), 1)
    for s in range(steps + 1):
        r = r1 + round(dr * s / steps)
        c = c1 + round(dc * s / steps)
        if 0 <= r < H and 0 <= c < W:
            result[r][c] = color

def order_polygon(points):
    """Order points to form a polygon (sort by angle around centroid)."""
    n = len(points)
    if n <= 2:
        return points
    cr = sum(p[0] for p in points) / n
    cc = sum(p[1] for p in points) / n
    return sorted(points, key=lambda p: math.atan2(p[0]-cr, p[1]-cc))

import math
from collections import defaultdict

def transform(grid):
    H = len(grid)
    W = len(grid[0])

    # Find connected components (4-connected)
    visited = set()
    components = []
    for r in range(H):
        for c in range(W):
            if grid[r][c] != 0 and (r, c) not in visited:
                color = grid[r][c]
                comp = []
                stack = [(r, c)]
                while stack:
                    cr, cc = stack.pop()
                    if (cr, cc) in visited or grid[cr][cc] != color:
                        continue
                    visited.add((cr, cc))
                    comp.append((cr, cc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < H and 0 <= nc < W and (nr, nc) not in visited:
                            stack.append((nr, nc))
                components.append(comp)

    # Classify pixels
    anchors = defaultdict(list)
    fixed = set()
    for comp in components:
        if len(comp) >= 2:
            for p in comp:
                fixed.add(p)
        else:
            p = comp[0]
            anchors[grid[p[0]][p[1]]].append(p)

    # Sort colors by sum of all pixel positions (outer first)
    def color_key(color):
        pts = anchors.get(color, [])
        if not pts:
            return float('inf')
        return sum(r + c for r, c in pts)

    color_order = sorted(anchors.keys(), key=color_key)

    # Draw shapes (outer first, inner overwrites)
    result = [[0]*W for _ in range(H)]

    for color in color_order:
        pts = sorted(anchors[color], key=lambda p: (p[0], p[1]))
        if len(pts) == 1:
            p = pts[0]
            # Find nearest fixed pixel of same color
            same_fixed = [f for f in fixed if grid[f[0]][f[1]] == color]
            if same_fixed:
                target = min(same_fixed, key=lambda f: abs(f[0]-p[0]) + abs(f[1]-p[1]))
                draw_line(result, p, target, color, H, W)
            else:
                result[p[0]][p[1]] = color
        elif len(pts) >= 2:
            # Open polyline through sorted points
            for i in range(len(pts) - 1):
                draw_line(result, pts[i], pts[i+1], color, H, W)

    # Place fixed pixels
    for (r, c) in fixed:
        result[r][c] = grid[r][c]

    return result

def draw_line(result, p1, p2, color, H, W):
    r1, c1 = p1
    r2, c2 = p2
    if r1 == r2 and c1 == c2:
        result[r1][c1] = color
        return
    steps = max(abs(r2-r1), abs(c2-c1))
    for i in range(steps + 1):
        t = i / steps
        r = round(r1 + (r2-r1)*t)
        c = round(c1 + (c2-c1)*t)
        if 0 <= r < H and 0 <= c < W:
            result[r][c] = color

import numpy as np
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    grid = [row[:] for row in grid]
    R = len(grid)
    C = len(grid)

    # Step 1: Find all 0 positions
    zero_positions = set()
    for r in range(R):
        for c in range(C):
            if grid[r][c] == 0:
                zero_positions.add((r, c))

    # Step 2: Build "filled" grid (0s become 1s)
    filled = [[0]*C for _ in range(R)]
    for r in range(R):
        for c in range(C):
            if grid[r][c] == 1 or (r, c) in zero_positions:
                filled[r][c] = 1
            else:
                filled[r][c] = 0

    # Step 3: Flood fill from boundary to find "outside" cells
    # A cell is "wall" if filled[r][c] == 1
    outside = [[False]*C for _ in range(R)]
    queue = deque()
    for c in range(C):
        if filled[0][c] == 0:
            outside[0][c] = True
            queue.append((0, c))
        if filled[R-1][c] == 0:
            outside[R-1][c] = True
            queue.append((R-1, c))
    for r in range(R):
        if filled[r][0] == 0:
            outside[r][0] = True
            queue.append((r, 0))
        if filled[r][C-1] == 0:
            outside[r][C-1] = True
            queue.append((r, C-1))

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < R and 0 <= nc < C and not outside[nr][nc] and filled[nr][nc] == 0:
                outside[nr][nc] = True
                queue.append((nr, nc))

    # Step 4: Find "inside" components (non-1, non-outside)
    visited = [[False]*C for _ in range(R)]
    inside_components = []
    for r in range(R):
        for c in range(C):
            if filled[r][c] == 0 and not outside[r][c] and not visited[r][c]:
                # BFS to find this component
                comp = []
                q = deque([(r, c)])
                visited[r][c] = True
                while q:
                    cr, cc = q.popleft()
                    comp.append((cr, cc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < R and 0 <= nc < C and not visited[nr][nc] and filled[nr][nc] == 0 and not outside[nr][nc]:
                            visited[nr][nc] = True
                            q.append((nr, nc))
                inside_components.append(comp)

    inside_cells = set()
    for comp in inside_components:
        for cell in comp:
            inside_cells.add(cell)

    # Step 5: Find 1-components and their adjacency to inside
    one_visited = [[False]*C for _ in range(R)]
    best_score = 0
    best_component = []

    for r in range(R):
        for c in range(C):
            if filled[r][c] == 1 and not one_visited[r][c]:
                # BFS to find this 1-component
                comp = []
                q = deque([(r, c)])
                one_visited[r][c] = True
                while q:
                    cr, cc = q.popleft()
                    comp.append((cr, cc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < R and 0 <= nc < C and not one_visited[nr][nc] and filled[nr][nc] == 1:
                            one_visited[nr][nc] = True
                            q.append((nr, nc))

                # Count adjacency to inside cells
                adj_count = 0
                for cr, cc in comp:
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if (nr, nc) in inside_cells:
                            adj_count += 1

                if adj_count > best_score:
                    best_score = adj_count
                    best_component = comp

    # Step 6: Apply changes
    result = [row[:] for row in grid]

    # Change 0s to 1s
    for r, c in zero_positions:
        result[r][c] = 1

    # Change best 1-component to 0s
    for r, c in best_component:
        result[r][c] = 0

    return result

import numpy as np
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    R = len(grid)
    C = len(grid)
    result = [row[:] for row in grid]

    # Find all 1-cells
    ones = [(r, c) for r in range(R) for c in range(C) if grid[r][c] == 1]
    if not ones:
        return result

    # Find bounding box of all 1-cells
    rmin = min(r for r, c in ones)
    rmax = max(r for r, c in ones)
    cmin = min(c for r, c in ones)
    cmax = max(c for r, c in ones)

    # Find largest rectangle of 1s within the bounding box (remove region)
    best_area = 0
    best_rect = None  # (r1, c1, r2, c2)

    for r1 in range(rmin, rmax + 1):
        for c1 in range(cmin, cmax + 1):
            for r2 in range(r1, rmax + 1):
                for c2 in range(c1, cmax + 1):
                    # Check if all cells in rectangle (r1,c1)-(r2,c2) are 1
                    all_one = True
                    for rr in range(r1, r2 + 1):
                        for cc in range(c1, c2 + 1):
                            if grid[rr][cc] != 1:
                                all_one = False
                                break
                        if not all_one:
                            break
                    if all_one:
                        area = (r2 - r1 + 1) * (c2 - c1 + 1)
                        if area > best_area:
                            best_area = area
                            best_rect = (r1, c1, r2, c2)

    # Find bounding box of all 0-cells (fill region)
    zeros = [(r, c) for r in range(R) for c in range(C) if grid[r][c] == 0]

    if best_rect and best_area > 1:
        # Apply remove: set 1s in best_rect to 0
        r1, c1, r2, c2 = best_rect
        for r in range(r1, r2 + 1):
            for c in range(c1, c2 + 1):
                if grid[r][c] == 1:
                    result[r][c] = 0
        # Set any 2s in the remove rect to 0 as well
        for r in range(r1, r2 + 1):
            for c in range(c1, c2 + 1):
                if grid[r][c] not in (0, 1, 3):
                    result[r][c] = 0

    # Apply fill: set 0s in their bounding box to 1
    if zeros:
        zr1 = min(r for r, c in zeros)
        zr2 = max(r for r, c in zeros)
        zc1 = min(c for r, c in zeros)
        zc2 = max(c for r, c in zeros)
        for r in range(zr1, zr2 + 1):
            for c in range(zc1, zc2 + 1):
                if grid[r][c] == 0:
                    result[r][c] = 1

    # Set remaining non-1, non-3 cells (like 2s) to 0
    for r in range(R):
        for c in range(C):
            if grid[r][c] not in (0, 1, 3):
                result[r][c] = 0

    return result

def transform(grid):
    from collections import Counter

    rows = len(grid)
    cols = len(grid[0])

    # Find the vertical line column
    best_col = 0
    best_score = 0
    for c in range(cols):
        col_vals = [grid[r][c] for r in range(rows)]
        for v in range(1, 10):
            cnt = col_vals.count(v)
            if cnt > best_score:
                best_score = cnt
                best_col = c

    line_col = best_col
    line_color = grid[0][line_col]

    output = [row[:] for row in grid]

    for r in range(rows):
        # Find contiguous non-zero segment on left (adjacent to line)
        left_seg = []
        for c in range(line_col - 1, -1, -1):
            if grid[r][c] != 0 and grid[r][c] != line_color:
                left_seg.append(grid[r][c])
            else:
                break
        left_seg.reverse()

        # Find contiguous non-zero segment on right (adjacent to line)
        right_seg = []
        for c in range(line_col + 1, cols):
            if grid[r][c] != 0 and grid[r][c] != line_color:
                right_seg.append(grid[r][c])
            else:
                break

        if left_seg and not right_seg:
            segment = left_seg
            side = 'right'
        elif right_seg and not left_seg:
            segment = right_seg
            side = 'left'
        else:
            continue

        color_counts = Counter(segment)

        if len(color_counts) == 1:
            color = segment[0]
            length = len(segment)
            pattern = [0] * length
            pattern[0] = color
        else:
            # Multi-color
            seen = []
            for v in segment:
                if v not in seen:
                    seen.append(v)
            color_order = list(reversed(seen))

            c0, c1 = color_order[0], color_order[1]
            n0 = color_counts[c0]
            n1 = color_counts[c1]
            period = n0 * n1

            if n0 == 1:
                pattern = [c0]
            else:
                seg_from_line = list(reversed(segment)) if side == 'right' else segment
                first_pos_of_c1 = seg_from_line.index(c1)
                c1_pos = (first_pos_of_c1 + 1) % period

                pattern = [0] * period
                for i in range(period):
                    if i % 2 == 0:
                        pattern[i] = c0
                    elif i == c1_pos:
                        pattern[i] = c1

        # Apply pattern
        if side == 'right':
            for j in range(cols - line_col - 1):
                output[r][line_col + 1 + j] = pattern[j % len(pattern)]
        else:
            for j in range(line_col):
                output[r][line_col - 1 - j] = pattern[j % len(pattern)]

    return output

def transform(grid):
    from collections import deque

    h = len(grid)
    w = len(grid[0])
    if h == 0 or w == 0:
        return [row[:] for row in grid]

    grid_arr = [[grid[i][j] for j in range(w)] for i in range(h)]

    visited = [[False]*w for _ in range(h)]
    components = []

    for i in range(h):
        for j in range(w):
            if grid_arr[i][j] != 0 and not visited[i][j]:
                color = grid_arr[i][j]
                queue = deque([(i, j)])
                visited[i][j] = True
                comp = []
                while queue:
                    r, c = queue.popleft()
                    comp.append((r, c))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = r+dr, c+dc
                        if 0 <= nr < h and 0 <= nc < w and not visited[nr, nc] and grid_arr[nr, nc] == color:
                            visited[nr, nc] = True
                            queue.append((nr, nc))
                components.append((color, comp))

    structures = [(color, comp) for color, comp in components if len(comp) >= 4]
    specials = [(color, comp) for color, comp in components if len(comp) < 4]

    if not structures and components:
        structures = [components[0]]
        specials = components[1:]

    result = [row[:] for row in grid]

    for struct_color, struct in structures:
        struct_set = set(struct)

        nearby_specials = []
        for spec_color, spec_comp in specials:
            for sp in spec_comp:
                sr, sc = sp
                if any(abs(sr-sr2) <= 2 and abs(sc-sc2) <= 2 for sr2, sc2 in struct):
                    nearby_specials.append((sr, sc, spec_color))

        if not nearby_specials:
            continue

        for sr, sc, _ in nearby_specials:
            result[sr][sc] = 0

        rows = [p[0] for p in struct]
        cols = [p[1] for p in struct]
        rmin, rmax = min(rows), max(rows)
        cmin, cmax = min(cols), max(cols)

        top_cov = sum(1 for c in range(cmin, cmax+1) if (rmin, c) in struct_set)
        bot_cov = sum(1 for c in range(cmin, cmax+1) if (rmax, c) in struct_set)
        left_cov = sum(1 for r in range(rmin, rmax+1) if (r, cmin) in struct_set)
        right_cov = sum(1 for r in range(rmin, rmax+1) if (r, cmax) in struct_set)

        h_extent = cmax - cmin + 1
        v_extent = rmax - rmin + 1

        if h_extent >= v_extent:
            scores = {'up': (top_cov, 1), 'down': (bot_cov, 1), 'left': (left_cov, 0), 'right': (right_cov, 0)}
        else:
            scores = {'up': (top_cov, 0), 'down': (bot_cov, 0), 'left': (left_cov, 1), 'right': (right_cov, 1)}

        direction = min(scores, key=scores.get)

        if direction == 'up':
            exit_row = rmin
            min_pos, max_pos = 0, rmin - 1
        elif direction == 'down':
            exit_row = rmax
            min_pos, max_pos = rmax + 1, h - 1
        elif direction == 'left':
            exit_col = cmin
            min_pos, max_pos = 0, cmin - 1
        else:
            exit_col = cmax
            min_pos, max_pos = cmax + 1, w - 1

        available = max_pos - min_pos + 1
        if available <= 0:
            continue

        n_specials = len(nearby_specials)
        spec_color = nearby_specials[0][2]

        if direction in ('up', 'down'):
            best_col = None
            best_count = -1
            for c in range(cmin, cmax + 1):
                count = sum(1 for r in range(rmin, rmax + 1) if (r, c) in struct_set)
                if count > best_count:
                    best_count = count
                    best_col = c

            count_to_fill = min(n_specials, available)
            if direction == 'up':
                positions = list(range(min_pos, min_pos + count_to_fill))
            else:
                positions = list(range(max_pos - count_to_fill + 1, max_pos + 1))

            for pos in positions:
                result[pos][best_col] = spec_color
        else:
            best_row = None
            best_count = -1
            for r in range(rmin, rmax + 1):
                count = sum(1 for c in range(cmin, cmax + 1) if (r, c) in struct_set)
                if count > best_count:
                    best_count = count
                    best_row = r

            count_to_fill = min(n_specials, available)
            if direction == 'left':
                positions = list(range(min_pos, min_pos + count_to_fill))
            else:
                positions = list(range(max_pos - count_to_fill + 1, max_pos + 1))

            for pos in positions:
                result[best_row][pos] = spec_color

    return result

def transform(grid):
    from collections import deque

    h = len(grid)
    w = len(grid[0])
    if h == 0 or w == 0:
        return [row[:] for row in grid]

    grid_arr = [[grid[i][j] for j in range(w)] for i in range(h)]

    # Find connected components (4-connectivity)
    visited = [[False] * w for _ in range(h)]
    components = []

    for i in range(h):
        for j in range(w):
            if grid_arr[i][j] != 0 and not visited[i][j]:
                color = grid_arr[i][j]
                queue = deque([(i, j)])
                visited[i][j] = True
                comp = []
                while queue:
                    r, c = queue.popleft()
                    comp.append((r, c))
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < h and 0 <= nc < w and not visited[nr][nc] and grid_arr[nr][nc] == color:
                            visited[nr][nc] = True
                            queue.append((nr, nc))
                components.append((color, comp))

    if not components:
        return [row[:] for row in grid]

    result = [row[:] for row in grid]
    n = len(components)

    # Determine associations: which specials belong to which structure
    associations = [[] for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i == j:
                continue
            color_a, comp_a = components[i]
            color_b, comp_b = components[j]
            if len(comp_a) <= len(comp_b):
                continue
            # Check if any pixel of comp_b is within Chebyshev distance 2 of comp_a
            near = False
            for (br, bc) in comp_b:
                for (ar, ac) in comp_a:
                    if abs(br - ar) <= 2 and abs(bc - ac) <= 2:
                        near = True
                        break
                if near:
                    break
            if near:
                associations[i].append(j)

    # Process each structure
    for s_idx in range(n):
        if not associations[s_idx]:
            continue

        struct_color, struct = components[s_idx]
        struct_set = set(struct)

        # Collect special pixels
        special_pixels = []
        special_color = None
        for sp_idx in associations[s_idx]:
            sp_color, sp_comp = components[sp_idx]
            if special_color is None:
                special_color = sp_color
            for (r, c) in sp_comp:
                special_pixels.append((r, c))

        if not special_pixels:
            continue

        # Remove special pixels
        for (r, c) in special_pixels:
            result[r][c] = 0

        # Structure bounds
        rows = [p[0] for p in struct]
        cols = [p[1] for p in struct]
        rmin, rmax = min(rows), max(rows)
        cmin, cmax = min(cols), max(cols)

        # Edge coverage
        top_cov = sum(1 for c in range(cmin, cmax + 1) if (rmin, c) in struct_set)
        bot_cov = sum(1 for c in range(cmin, cmax + 1) if (rmax, c) in struct_set)
        left_cov = sum(1 for r in range(rmin, rmax + 1) if (r, cmin) in struct_set)
        right_cov = sum(1 for r in range(rmin, rmax + 1) if (r, cmax) in struct_set)

        edges = {'up': top_cov, 'down': bot_cov, 'left': left_cov, 'right': right_cov}
        min_cov = min(edges.values())
        candidates = [d for d in edges if edges[d] == min_cov]

        if len(candidates) == 1:
            direction = candidates[0]
        else:
            # Tie-break: exit in direction away from special pixels
            avg_sr = sum(p[0] for p in special_pixels) / len(special_pixels)
            avg_sc = sum(p[1] for p in special_pixels) / len(special_pixels)
            ctr = (rmin + rmax) / 2.0
            ctc = (cmin + cmax) / 2.0
            dr = avg_sr - ctr
            dc = avg_sc - ctc

            best_dir = candidates[0]
            best_score = -1
            for d in candidates:
                score = 0
                if d == 'up' and dr > 0:
                    score = abs(dr)
                elif d == 'down' and dr < 0:
                    score = abs(dr)
                elif d == 'left' and dc > 0:
                    score = abs(dc)
                elif d == 'right' and dc < 0:
                    score = abs(dc)
                if score > best_score:
                    best_score = score
                    best_dir = d
            direction = best_dir

        # Place specials in a line from the exit
        if direction == 'up':
            exit_col = None
            for c in range(cmin, cmax + 1):
                if (rmin, c) in struct_set:
                    if exit_col is None or (rmin, c) == (rmin, c):
                        exit_col = c
                    # pick the one closest to special avg col
                    if exit_col is None:
                        exit_col = c
            # Better: pick the edge pixel closest to the special pixels' average column
            edge_pixels = [(rmin, c) for c in range(cmin, cmax + 1) if (rmin, c) in struct_set]
            if edge_pixels:
                exit_col = min(edge_pixels, key=lambda p: abs(p[1] - avg_sc))[1]
            else:
                exit_col = cmin

            count = min(len(special_pixels), rmin)
            for i in range(count):
                result[rmin - 1 - i][exit_col] = special_color

        elif direction == 'down':
            edge_pixels = [(rmax, c) for c in range(cmin, cmax + 1) if (rmax, c) in struct_set]
            avg_sc = sum(p[1] for p in special_pixels) / len(special_pixels)
            if edge_pixels:
                exit_col = min(edge_pixels, key=lambda p: abs(p[1] - avg_sc))[1]
            else:
                exit_col = cmin

            count = min(len(special_pixels), h - 1 - rmax)
            for i in range(count):
                result[rmax + 1 + i][exit_col] = special_color

        elif direction == 'left':
            edge_pixels = [(r, cmin) for r in range(rmin, rmax + 1) if (r, cmin) in struct_set]
            avg_sr = sum(p[0] for p in special_pixels) / len(special_pixels)
            if edge_pixels:
                exit_row = min(edge_pixels, key=lambda p: abs(p[0] - avg_sr))[0]
            else:
                exit_row = rmin

            count = min(len(special_pixels), cmin)
            for i in range(count):
                result[exit_row][cmin - 1 - i] = special_color

        elif direction == 'right':
            edge_pixels = [(r, cmax) for r in range(rmin, rmax + 1) if (r, cmax) in struct_set]
            avg_sr = sum(p[0] for p in special_pixels) / len(special_pixels)
            if edge_pixels:
                exit_row = min(edge_pixels, key=lambda p: abs(p[0] - avg_sr))[0]
            else:
                exit_row = rmin

            count = min(len(special_pixels), w - 1 - cmax)
            for i in range(count):
                result[exit_row][cmax + 1 + i] = special_color

    return result

def transform(grid):
    from collections import defaultdict

    h = len(grid)
    w = len(grid[0])
    out = [[8] * w for _ in range(h)]

    color_pixels = defaultdict(list)
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 8:
                color_pixels[grid[r][c]].append((r, c))

    shapes = []
    for color, pixels in color_pixels.items():
        rows = [p[0] for p in pixels]
        cols = [p[1] for p in pixels]
        r_min, r_max = min(rows), max(rows)
        c_min, c_max = min(cols), max(cols)
        bh = r_max - r_min + 1
        bw = c_max - c_min + 1
        shapes.append((color, bh, bw))

    def get_shape(bh, bw):
        if (bh, bw) in [(1, 2), (2, 1)]:
            return [(0, 0), (0, 1)]
        elif (bh, bw) == (2, 4):
            return [(0, 1), (1, 0), (1, 1), (1, 2), (2, 0), (2, 1), (2, 2), (3, 1)]
        elif (bh, bw) == (3, 3):
            return [(0, 1), (1, 0), (1, 1), (1, 2), (1, 3),
                    (2, 0), (2, 1), (2, 2), (2, 3), (3, 1)]
        elif (bh, bw) == (3, 4):
            return [(0, 0), (0, 1), (1, 1), (1, 2), (1, 3),
                    (2, 1), (2, 2), (2, 3), (3, 0), (3, 1)]
        elif (bh, bw) in [(4, 2), (2, 2)]:
            return [(0, 1), (0, 2), (1, 0), (1, 1), (1, 2), (1, 3),
                    (2, 0), (2, 1), (2, 2), (2, 3), (3, 1), (3, 2)]
        elif (bh, bw) == (3, 2):
            return [(0, 0), (0, 1), (1, 0), (1, 1), (2, 0), (2, 1)]
        else:
            return None

    placed = []
    for color, bh, bw in shapes:
        s = get_shape(bh, bw)
        if s is None:
            continue
        sh = max(r for r, c in s) + 1
        sw = max(c for r, c in s) + 1
        x_center = (sw - 1) / 2.0
        placed.append((x_center, color, s, sh, sw))

    placed.sort(key=lambda x: x[0])

    if not placed:
        return out

    max_sh = max(sh for _, _, _, sh, _ in placed)
    y_center = h / 2.0
    y_min = int(round(y_center - max_sh / 2.0))

    # Place with 1-pixel gap between shapes, centered
    total_width = sum(sw for _, _, _, _, sw in placed) + (len(placed) - 1)
    x_start_offset = int(round(w / 2.0 - total_width / 2.0))

    x_pos = x_start_offset
    for i, (xc, color, s, sh, sw) in enumerate(placed):
        for dr, dc in s:
            r = y_min + dr
            c = x_pos + dc
            if 0 <= r < h and 0 <= c < w:
                out[r][c] = color
        x_pos += sw + 1

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    from collections import deque, Counter

    h = len(grid)
    w = len(grid[0])

    colors = set()
    for r in range(h):
        for c in range(w):
            colors.add(grid[r][c])

    structure_color = None
    for color in colors:
        bt = set()
        for c in range(w):
            if grid[0][c] == color: bt.add('t')
            if grid[h-1][c] == color: bt.add('b')
        for r in range(h):
            if grid[r][0] == color: bt.add('l')
            if grid[r][w-1] == color: bt.add('r')
        if len(bt) >= 2:
            structure_color = color
            break

    cc = Counter()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != structure_color:
                cc[grid[r][c]] += 1
    background = cc.most_common(1)[0][0]

    seeds = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
             if grid[r][c] != structure_color and grid[r][c] != background]

    visited = [[False]*w for _ in range(h)]
    regions = []
    for sr in range(h):
        for sc in range(w):
            if grid[sr][sc] == structure_color or visited[sr][sc]:
                continue
            cells = []
            q = deque([(sr, sc)])
            visited[sr][sc] = True
            while q:
                r, c = q.popleft()
                cells.append((r, c))
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < h and 0 <= nc < w and not visited[nr][nc] and grid[nr][nc] != structure_color:
                        visited[nr][nc] = True
                        q.append((nr, nc))
            regions.append(cells)

    result = [row[:] for row in grid]

    for region in regions:
        rset = set(region)
        rseeds = [(r,c,col) for r,c,col in seeds if (r,c) in rset]
        if not rseeds:
            continue

        if len(rseeds) == 1:
            col = rseeds[0][2]
            for r, c in region:
                result[r][c] = col
            continue

        # Distance to boundary via BFS
        boundary = set()
        for r, c in region:
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r+dr, c+dc
                if (nr, nc) not in rset:
                    boundary.add((r, c))
                    break

        dist_to_boundary = {}
        bfs_q = deque()
        for cell in boundary:
            dist_to_boundary[cell] = 0
            bfs_q.append(cell)
        while bfs_q:
            r, c = bfs_q.popleft()
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r+dr, c+dc
                if (nr, nc) in rset and (nr, nc) not in dist_to_boundary:
                    dist_to_boundary[(nr, nc)] = dist_to_boundary[(r,c)] + 1
                    bfs_q.append((nr, nc))

        level_color = {}
        for r, c, col in rseeds:
            level = dist_to_boundary[(r, c)]
            level_color[level] = col

        levels = sorted(level_color.keys())

        for r, c in region:
            d = dist_to_boundary[(r, c)]
            if d in level_color:
                result[r][c] = level_color[d]
            else:
                result[r][c] = level_color[levels[d % len(levels)]]

    return result

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    W = len(grid[0])
    result = [row[:] for row in grid]

    # Find all contiguous 7-groups
    seven_groups = {}
    for r in range(H):
        groups = []
        c = 0
        while c < W:
            if grid[r][c] == 7:
                start = c
                while c < W and grid[r][c] == 7:
                    c += 1
                groups.append((start, c - 1))
            else:
                c += 1
        if groups:
            seven_groups[r] = groups

    # Replace 7-groups with 868 pattern
    for r in seven_groups:
        for (s, e) in seven_groups[r]:
            length = e - s + 1
            for i in range(length):
                pos = s + i
                if i == 0 or i == length - 1:
                    result[r][pos] = 8
                else:
                    result[r][pos] = 6

    content_rows = set(seven_groups.keys())

    # Place 6s in frame rows at centers of adjacent 7-groups
    for r in range(H):
        if r in content_rows or r == H - 1:
            continue
        if 8 not in grid[r] and 3 not in grid[r]:
            continue

        centers = set()
        if (r - 1) in seven_groups:
            for (s, e) in seven_groups[r - 1]:
                centers.add((s + e) // 2)
        if (r + 1) in seven_groups:
            for (s, e) in seven_groups[r + 1]:
                centers.add((s + e) // 2)

        for c in centers:
            if result[r][c] == 8:
                result[r][c] = 6

    # Edge 3/8 changes
    for r in range(H):
        if r in content_rows or r == H - 1:
            continue
        if 8 not in grid[r] and 3 not in grid[r]:
            continue
        if all(grid[r][c] == 0 for c in range(W)):
            continue

        above_content = (r - 1) in content_rows
        below_content = (r + 1) in content_rows

        if above_content and below_content:
            for c in [0, 1, W-2, W-1]:
                if 0 <= c < W and result[r][c] == 8:
                    result[r][c] = 3
        else:
            for c in [0, W-1]:
                if result[r][c] == 3:
                    result[r][c] = 8

    # Bottom row
    r = H - 1
    if (r - 1) in seven_groups:
        for (s, e) in seven_groups[r - 1]:
            center = (s + e) // 2
            if result[r][center] == 8:
                result[r][center] = 6

    for c in range(W):
        if grid[0][c] == 0 and grid[r][c] != 0 and result[r][c] == 8:
            result[r][c] = 3

    return result

def transform(grid):
    H = len(grid)
    W = len(grid[0])
    result = [row[:] for row in grid]

    content_rows = set(r for r in range(H) if 7 in grid[r])
    frame_rows = [r for r in range(H) if r not in content_rows]

    # Step 1: Replace 7-groups with 868
    for r in content_rows:
        for s, e in find_7_groups(grid[r]):
            length = e - s + 1
            for i in range(length):
                result[r][s + i] = 8 if (i == 0 or i == length - 1) else 6

    # Step 2: Place 6s in frame rows at centers of adjacent 7-groups
    for r in frame_rows:
        centers = set()
        if r - 1 in content_rows:
            for s, e in find_7_groups(grid[r-1]):
                centers.add((s + e) // 2)
        if r + 1 in content_rows:
            for s, e in find_7_groups(grid[r+1]):
                centers.add((s + e) // 2)
        for c in centers:
            if result[r][c] == 8:
                result[r][c] = 6

    # Step 3: Find 0-channel connected components in the frame
    zero_frame = set()
    for r in frame_rows:
        for c in range(W):
            if grid[r][c] == 0:
                zero_frame.add((r, c))

    parent = {cell: cell for cell in zero_frame}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py

    # Horizontal within same frame row
    for r in frame_rows:
        for c in range(W - 1):
            if (r, c) in zero_frame and (r, c + 1) in zero_frame:
                union((r, c), (r, c + 1))

    # Vertical between consecutive frame rows
    for i in range(len(frame_rows) - 1):
        r1, r2 = frame_rows[i], frame_rows[i + 1]
        for c in range(W):
            if (r1, c) in zero_frame and (r2, c) in zero_frame:
                ok = all(grid[cr][c] == 0 for cr in range(r1 + 1, r2))
                if ok:
                    union((r1, c), (r2, c))

    # Find which components touch an edge column
    edge_components = set()
    for cell in zero_frame:
        r, c = cell
        if c == 0 or c == W - 1:
            edge_components.add(find(cell))

    # For each frame row, find "boundary" positions of edge-connected channels
    # These are 8-cells adjacent to 0-cells in edge-connected components
    for r in frame_rows:
        channel_cells = set()
        for c in range(W):
            if (r, c) in zero_frame and find((r, c)) in edge_components:
                channel_cells.add(c)

        # Boundary positions: 8-cells adjacent to channel 0-cells
        boundary = set()
        for c in channel_cells:
            for nc in [c - 1, c + 1]:
                if 0 <= nc < W and grid[r][nc] == 8:
                    boundary.add(nc)

        # Also, edge positions that are in the channel
        for c in channel_cells:
            if c == 0 or c == W - 1:
                boundary.add(c)

        # Edge positions NOT in channel: 3→8
        # Edge positions in boundary: 8→3
        for c in boundary:
            if result[r][c] == 8:
                result[r][c] = 3

        # For edges not in any channel: 3→8
        for c in [0, W - 1]:
            if c not in channel_cells and c not in boundary:
                if result[r][c] == 3:
                    result[r][c] = 8

    return result


def find_7_groups(row):
    groups = []
    c = 0
    while c < len(row):
        if row[c] == 7:
            start = c
            while c < len(row) and row[c] == 7:
                c += 1
            groups.append((start, c - 1))
        else:
            c += 1
    return groups
